// <auto-generated companion /> — payload delivered to script signal listeners.
#nullable enable

namespace Spark.Bindings;

/// <summary>Untyped signal payload (interpretation depends on <see cref="SignalId"/>).</summary>
public readonly struct SignalReceivedPayload
{
    public nint RawPointer { get; init; }
    public ulong A { get; init; }
    public ulong B { get; init; }

    /// <summary>When <c>ptr</c> holds a <see cref="GameObject"/> (triggers, death instigator, …).</summary>
    public GameObject? TryGetObjectFromPointer()
        => RawPointer == 0 ? null : new GameObject(RawPointer);

    /// <summary>When <c>ptr</c> holds a null-terminated UTF-8 string (animation/input event names).</summary>
    public unsafe string? TryGetUtf8StringFromPointer()
        => RawPointer == 0 ? null : InteropUtf8.PtrToString((sbyte*)RawPointer);
}

public delegate void SignalListenerCallback(GameObject owner, SignalId id, in SignalReceivedPayload payload);
